require_once __DIR__.'/config.php';require_login();$pageTitle='Create a study group';$errors=[];$subjects=$pdo->query('SELECT id,name FROM subjects ORDER BY name')->fetchAll();
if(is_post()){verify_csrf();$name=posted_string('name',150);$description=posted_string('description',3000);$subject=valid_id($_POST['subject_id']??0);if(mb_strlen($name)<4)$errors[]='Group name must be at least 4 characters.';if(mb_strlen($description)<20)$errors[]='Add a description of at least 20 characters.';if(!$subject)$errors[]='Choose a subject.';if(!$errors){$pdo->beginTransaction();$pdo->prepare('INSERT INTO study_groups(name,description,subject_id,creator_id) VALUES(?,?,?,?)')->execute([$name,$description,$subject,current_user()['id']]);$gid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO group_members(group_id,user_id) VALUES(?,?)')->execute([$gid,current_user()['id']]);$pdo->commit();set_flash('success','Your study group is ready.');redirect('group.php?id='.$gid);}}
require __DIR__.'/includes/header.php';?><section class="page-hero"><div class="container"><span class="eyebrow">START SOMETHING TOGETHER</span><h1>Create a study group</h1><p>Give your group a clear purpose so other students know whether it is right for them.</p></div></section><div class="page-content"><div class="container"><form class="form-card" method="post"><?= csrf_field() ?><?php if($errors): ?><div class="alert alert-error"><ul><?php foreach($errors as $err): ?><li><?= e($err) ?></li><?php endforeach; ?></ul></div><?php endif; ?><div class="form-group"><label for="name">Group name</label><input id="name" name="name" maxlength="150" value="<?= e($_POST['name']??'') ?>" required placeholder="e.g. Data Structures Study Buddies"></div><div class="form-group"><label for="subject_id">Main subject</label><select id="subject_id" name="subject_id" required><option value="">Choose a subject</option><?php foreach($subjects as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label for="description">Group description</label><textarea id="description" name="description" required maxlength="3000" placeholder="What will members study? How often will you meet?"><?= e($_POST['description']??'') ?></textarea></div><button class="btn btn-primary">Create group</button> <a class="btn btn-outline" href="groups.php">Cancel</a></form></div></div><?php require __DIR__.'/includes/footer.php';?>
